     * The window/surface metadata declared by the root's {@link WindowMetadata}
     * modifier, or {@code null}. The emitter binds these fields to their signals
     * after the mount render.
     */
    public WindowMetadata windowMetadata() {
        return windowMetadata;
    }

    /** Record the root-declared window metadata during its render. */
    void setWindowMetadata(WindowMetadata metadata) {
        this.windowMetadata = metadata;
    }

    /**
     * The button style active for the current render — the scoped environment value
     * {@link #BUTTON_STYLE}, defaulting to {@link PlainButtonStyle} when no scope
     * binds it.
     */
    public ButtonStyle buttonStyle() {
        ButtonStyle style = Environment.value(BUTTON_STYLE).get();
        return style != null ? style : PlainButtonStyle.INSTANCE;
    }

    /** The session's persistent state (null for a stateless environment). */
    public dev.pathland.view.state.PersistentState state() {
        return state;
    }

    /**
     * The label style active for the current render — the scoped environment value
     * {@link #LABEL_STYLE}, defaulting to {@link DefaultLabelStyle} when no scope
     * binds it.
     */
    public LabelStyle labelStyle() {
        LabelStyle style = Environment.value(LABEL_STYLE).get();
        return style != null ? style : DefaultLabelStyle.INSTANCE;
    }

    /**
     * The video style active for the current render — the scoped environment value
     * {@link #VIDEO_STYLE}, defaulting to {@link NativeVideoStyle}.
