import dev.pathland.view.ViewModifier;
import dev.pathland.view.emit.PathlandNode;

import java.util.Objects;
import java.util.function.Consumer;

/**
 * A tappable link that changes the route (spec DSL.md §4.5). With an explicit
 * {@link Router} it {@link Router#push(String) pushes} onto that router's
 * back-stack; the router-agnostic call ({@code NavigationLink.make(l -> l.to("/users"))})
 * declares a {@link NavOp#PUSH} intent that the emitter resolves to the **nearest
 * enclosing** {@link Router} — no router is threaded by hand. Renders through the
 * active {@code ButtonStyle} as a native {@code BUTTON}; its tap action is routed
 * via the emitter's tap/navigate-action registry exactly like a button.
 */
public final class NavigationLink implements View, Configurable<NavigationLink.Config> {

    /** {@link NavigationLink} values. */
    public static final class Config implements View.Config {

        private String label;
        private View labelView;
        private Router router;
        private String to;

        /** A plain text label. */
        public Config label(String label) {
            this.label = label;
            this.labelView = null;
            return this;
        }

        /** An arbitrary child view as the label. */
        public Config label(View label) {
            this.labelView = label;
            this.label = null;
            return this;
        }

        /** The explicit router to push onto (or {@code null} for the router-agnostic form). */
        public Config router(Router router) {
            this.router = router;
            return this;
        }

        /** The destination path. */
        public Config to(String to) {
            this.to = to;
            return this;
        }
    }

    private final Config config;

    private NavigationLink(Config config) {
        this.config = config;
    }

    /** Configure the link ({@code NavigationLink.make(l -> l.label(...).to(...))}). */
/** An empty NavigationLink (no values). */
    public static ViewBuilder<NavigationLink, Config> make() {
        return new ViewBuilder<>(new NavigationLink(new Config()));
    }

    public static ViewBuilder<NavigationLink, Config> make(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new NavigationLink(config));
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        Objects.requireNonNull(config.to, "to");
        View label = config.labelView != null
                ? config.labelView
                : Text.make(t -> t.text(config.label == null ? "" : config.label));
        if (config.router != null) {
            return Button.make(b -> b.action(() -> config.router.push(config.to)))
                    .children(label)
                    .renderNode(env);
        }
        // The tap's real effect is the declared navigation intent (`.push`), which the
        // host routes via navigateActions before tapActions; the button action is a
        // no-op placeholder (Button requires one).
        return Button.make(b -> b.action(() -> {}))
                .children(label)
                .modifiers(NavigationIntent.push(config.to))
                .renderNode(env);
    }
}package dev.pathland.view.router;

import dev.pathland.view.View;
import dev.pathland.view.ViewModifier;

/**
 * The navigation action modifier (spec DSL.md §4.5 "any component can change the
 * route"): marks a view as a route-changer, applied with
 * {@code .modifiers(NavigationIntent.navigate/push/replace(path))}. The intent is
 * resolved to the nearest enclosing {@link Router} by the emitter, so no router is
 * threaded by hand:
 *
 * <pre>{@code
 * Button.make(b -> b.title("Go to kitchen").action(...))
 *       .modifiers(NavigationIntent.navigate("/kitchen"));   // direct selection
 * Button.make(b -> b.title("Open item").action(...))
 *       .modifiers(NavigationIntent.push("/item/1"));        // drill-down (back-stack)
 * Button.make(b -> b.title("Swap").action(...))
 *       .modifiers(NavigationIntent.replace("/settings"));   // guard redirect / replace
 * }</pre>
 */
public final class NavigationIntent implements ViewModifier {

    private final String to;
    private final NavOp op;

    private NavigationIntent(String to, NavOp op) {
        this.to = to;
        this.op = op;
    }

    /** A {@link NavOp#NAVIGATE} route-change to {@code to}. */
    public static NavigationIntent navigate(String to) {
        return new NavigationIntent(to, NavOp.NAVIGATE);
    }

    /** A {@link NavOp#PUSH} route-change to {@code to} (drill-down). */
    public static NavigationIntent push(String to) {
        return new NavigationIntent(to, NavOp.PUSH);
    }

    /** A {@link NavOp#REPLACE} route-change to {@code to}. */
    public static NavigationIntent replace(String to) {
        return new NavigationIntent(to, NavOp.REPLACE);
    }

    @Override
    public View body(View content) {
        return new NavigationIntentView(content, to, op);
    }
}package dev.pathland.view.router;

/**
 * The navigation chrome mode of a {@code NavigationContainer} (spec DSL.md §4.5,
 * the {@code NAV_CHROME} 0x201B enum).
 *
 * <p>{@link #PLATFORM_DEFAULT} is the default: the <b>renderer</b> supplies the
 * navigation chrome — the platform's native navigation container where one exists
 * (GTK {@code AdwNavigationView}, {@code NavigationStack}, Compose
 * {@code NavHost}) and a renderer-drawn back affordance where none exists (the
 * DOM renderer shows a back button once {@code NAV_DEPTH &gt; 1}).
 *
 * <p>{@link #CUSTOM} means the <b>developer owns all navigation UI</b>: they draw
 * their own back buttons/bars in the destinations and call
 * {@code router.back()}/{@code navigate(...)} directly; the renderer adds no
 * chrome (no native header-bar back button, no DOM back button).
 */
public enum Chrome {

    PLATFORM_DEFAULT(0),
    CUSTOM(1);

    private final int wire;

    Chrome(int wire) {
        this.wire = wire;
    }

    /** The wire enum code for {@code NAV_CHROME} (F32). */
    public int wire() {
        return wire;
    }
}

