#[no_mangle]
pub unsafe extern "C" fn pathland_native_window_metadata(
    host: HostHandle,
    field: u32,
    signal: u32,
) -> u8 {
    u8::from(as_host(host).bind_window_metadata(field as u16, as_signal_id(signal)))
}

