    private static final ArrayDeque<Effect> QUEUE = new ArrayDeque<>();
    private static boolean flushing = false;

    private Scheduler() {}

    static synchronized void schedule(Effect effect) {
        if (!effect.scheduled) {
            effect.scheduled = true;
            QUEUE.add(effect);
        }
        flush();
